(3750747, 525708, 79164, '<td valign="top">Helemaal NIX, sorry !</td>', 'Helemaal NIX, sorry !', '2007-06-07 07:47:25.000000', NULL, 1),
(3750912, 529309, 79128, '<td valign="top">Nice crisp picture, good mirror effect.</td>', 'Nice crisp picture, good mirror effect.', '2007-06-07 09:56:07.000000', NULL, 1),
(3750919, 526264, 79128, '<td valign="top">Very cool, nice vivid colors.</td>', 'Very cool, nice vivid colors.', '2007-06-07 09:58:27.000000', NULL, 1),
(3750930, 528391, 79128, '<td valign="top">Is this a picture of a monitor?</td>', 'Is this a picture of a monitor?', '2007-06-07 10:01:30.000000', NULL, 1),
(3751158, 529321, 74534, '<td valign="top">This is a very good idea, you have a very good inner painter in you :) If this was a real person, I would have scored this a 9-10 probably.</td>', 'This is a very good idea, you have a very good inner painter in you :) If this was a real person, I would have scored this a 9-10 probably.', '2007-06-07 11:08:50.000000', NULL, 1),
(3751162, 527198, 74534, '<td valign="top">This is nicely done, I like the soft light and especially the "waves" at the bottom of the glass. I think most people will expect clearly visible "trails" of light, so you might get voted down.</td>', 'This is nicely done, I like the soft light and especially the "waves" at the bottom of the glass. I think most people will expect clearly visible "trails" of light, so you might get voted down.', '2007-06-07 11:09:56.000000', NULL, 1),
(3751173, 526866, 74534, '<td valign="top">Cool idea. Just wondering why you left the bottom of the can un-labeled. The lid is somewhat distracting, and so is the little thingy in the bottom left corner.</td>', 'Cool idea. Just wondering why you left the bottom of the can un-labeled. The lid is somewhat distracting, and so is the little thingy in the bottom left corner.', '2007-06-07 11:12:23.000000', NULL, 1),
(3751176, 528667, 74534, '<td valign="top">I like the warm glow a lot. However, the aspect ratio is too thin: by cropping out from the bottom you would have had a better aspect ratio, and you would have gotten rid of the annoying reflection in the plastic / vase whatever it is around the flower.</td>', 'I like the warm glow a lot. However, the aspect ratio is too thin: by cropping out from the bottom you would have had a better aspect ratio, and you would have gotten rid of the annoying reflection in the plastic / vase whatever it is around the flower.', '2007-06-07 11:13:50.000000', NULL, 1),
(3751181, 526617, 74534, '<td valign="top">This is a nice image, but I don''t see the Painting with Light effect. It would have to be either light clearly directed at an object of interest, or maybe trails of light, or maybe just a warm diffuse glow around something. This looks mostly like natural light to me.</td>', 'This is a nice image, but I don''t see the Painting with Light effect. It would have to be either light clearly directed at an object of interest, or maybe trails of light, or maybe just a warm diffuse glow around something. This looks mostly like natural light to me.', '2007-06-07 11:15:35.000000', NULL, 1),
