(3761351, 529235, 70596, '<td valign="top">One of the best executions of this popular idea.</td>', 'One of the best executions of this popular idea.', '2007-06-09 21:20:22.000000', NULL, 1),
(3761352, 529084, 70596, '<td valign="top">Great quality. Would be nice with a little more drama.</td>', 'Great quality. Would be nice with a little more drama.', '2007-06-09 21:21:26.000000', NULL, 1),
(3761429, 527780, 75122, '<td valign="top">The glare on the bottle is distracting.</td>', 'The glare on the bottle is distracting.', '2007-06-09 22:01:55.000000', NULL, 1),
(3761435, 528969, 75122, '<td valign="top">Neat Idea.  I esp. like the contrast between the soft swirl around the light and the harsh jagged lines above the batteries.</td>', 'Neat Idea.  I esp. like the contrast between the soft swirl around the light and the harsh jagged lines above the batteries.', '2007-06-09 22:05:11.000000', NULL, 1),
(3761446, 529183, 75122, '<td valign="top">I think this was a good idea, but the "light replacing water" is a little over blown.  Would have liked to see it softer and transition better over the flowers.</td>', 'I think this was a good idea, but the "light replacing water" is a little over blown.  Would have liked to see it softer and transition better over the flowers.', '2007-06-09 22:10:23.000000', NULL, 1),
(3761461, 528827, 67152, '<td valign="top">interesting perspective - the colors are interesting but I don''t really follow it</td>', 'interesting perspective - the colors are interesting but I don''t really follow it', '2007-06-09 22:17:23.000000', NULL, 1),
(3761464, 529230, 67152, '<td valign="top">i like the gold tones and the shape of the lines</td>', 'i like the gold tones and the shape of the lines', '2007-06-09 22:18:25.000000', NULL, 1),
(3761466, 529221, 67152, '<td valign="top">wonderful composition and lighting - very dramatic - and the ''face'' is quite humorous</td>', 'wonderful composition and lighting - very dramatic - and the ''face'' is quite humorous', '2007-06-09 22:18:58.000000', NULL, 1),
