(3761471, 529049, 67152, '<td valign="top">cool straws - but the lighting on right really seems out of balance</td>', 'cool straws - but the lighting on right really seems out of balance', '2007-06-09 22:20:40.000000', NULL, 1),
(3761472, 528750, 67152, '<td valign="top">nice macro on the glass - the mystical lines are pretty well done - and the colors are very attractive</td>', 'nice macro on the glass - the mystical lines are pretty well done - and the colors are very attractive', '2007-06-09 22:22:09.000000', NULL, 1),
