(3772136, 528801, 43073, '<td valign="top">I like this concept, and I think the execution is good, with good elements and composition; the hands are bit soft to my eyes, but other than that it''s excellent.</td>', 'I like this concept, and I think the execution is good, with good elements and composition; the hands are bit soft to my eyes, but other than that it''s excellent.', '2007-06-12 09:38:00.000000', NULL, 1),
(3772144, 529239, 43073, '<td valign="top">I really like this image; the blue is very effective, and the light from inside really adds to the effect of the image on the viewer. Good use of negative space in the lower portion, and in using the light from the sky to set off that portion of the image. 9</td>', 'I really like this image; the blue is very effective, and the light from inside really adds to the effect of the image on the viewer. Good use of negative space in the lower portion, and in using the light from the sky to set off that portion of the image. 9', '2007-06-12 09:40:29.000000', NULL, 1),
(3772147, 529194, 43073, '<td valign="top">I really like this image, from concept through to execution. It really speaks to me, telling me a story of artistic angst and passion; wonderful. Would have been a ten, but the noise in the body seemed a bit out of place with the rest of the image to me. 9</td>', 'I really like this image, from concept through to execution. It really speaks to me, telling me a story of artistic angst and passion; wonderful. Would have been a ten, but the noise in the body seemed a bit out of place with the rest of the image to me. 9', '2007-06-12 09:41:39.000000', NULL, 1),
(3772150, 528412, 43073, '<td valign="top">I like the use of the painted light here, accenting the main subject and creating interest. The shades and colors that appear throughout add to the effect for me. Nicely done. 9</td>', 'I like the use of the painted light here, accenting the main subject and creating interest. The shades and colors that appear throughout add to the effect for me. Nicely done. 9', '2007-06-12 09:42:27.000000', NULL, 1),
(3772163, 529221, 43073, '<td valign="top">I really like this image; subtle use of the light painting technique, but to wonderful effect. Great composition, interesting subject, perfect title. I''d go for a ride! 9</td>', 'I really like this image; subtle use of the light painting technique, but to wonderful effect. Great composition, interesting subject, perfect title. I''d go for a ride! 9', '2007-06-12 09:48:02.000000', NULL, 1),
