(3773065, 529296, 67697, '<td valign="top">My kids would think this is cool.  Great idea!</td>', 'My kids would think this is cool.  Great idea!', '2007-06-12 14:20:36.000000', NULL, 1),
(3773069, 526878, 67697, '<td valign="top">You have a good steady hand.  Nice concept and good lighting on the pot.</td>', 'You have a good steady hand.  Nice concept and good lighting on the pot.', '2007-06-12 14:21:22.000000', NULL, 1),
