(3773100, 529208, 67697, '<td valign="top">Nice job with making your arm look like it is slipping into the votex.</td>', 'Nice job with making your arm look like it is slipping into the votex.', '2007-06-12 14:28:42.000000', NULL, 1),
(3773103, 529286, 67697, '<td valign="top">Have they gone to Vegas to elope?  hehe<br/>Came back because I forgot to add that I liked the colors you used - they give off a good neon feel to the pic.</td>', 'Have they gone to Vegas to elope?  heheCame back because I forgot to add that I liked the colors you used - they give off a good neon feel to the pic.', '2007-06-12 14:29:46.000000', NULL, 1),
