(3773137, 524654, 71931, '<td valign="top">Nice shot, but not in the theme...</td>', 'Nice shot, but not in the theme...', '2007-06-12 14:42:13.000000', NULL, 1),
(3773143, 529177, 71931, '<td valign="top">This would have been much better if the bottle were tilted on its side, so that it looked like it really was pouring into the glass.  Nice effect, though.</td>', 'This would have been much better if the bottle were tilted on its side, so that it looked like it really was pouring into the glass.  Nice effect, though.', '2007-06-12 14:43:19.000000', NULL, 1),
(3773144, 529132, 71931, '<td valign="top">Not on the theme, but a nice shot, anyway.</td>', 'Not on the theme, but a nice shot, anyway.', '2007-06-12 14:43:46.000000', NULL, 1),
(3773148, 529154, 71931, '<td valign="top">ROFL!!</td>', 'ROFL!!', '2007-06-12 14:45:00.000000', NULL, 1),
